def tri(n):
    if n < 0:
        return []
    res = [0] * (n + 1)
    # tri(0) = 1 + 0/2 = 1
    res[0] = 1
    if n >= 1:
        # tri(1) is given as 3
        res[1] = 3
    for i in range(2, n + 1):
        if i % 2 == 0:
            # even: tri(i) = 1 + i/2
            res[i] = 1 + i // 2
        else:
            # odd and i >= 3: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            # but i+1 is even, so tri(i+1) = 1 + (i+1)/2
            res[i] = res[i-1] + res[i-2] + (1 + (i + 1) // 2)
    return res

