def Strongest_Extension(class_name, extensions):
    if not extensions:
        return class_name

    def strength(ext):
        cap = sum(1 for c in ext if c.isupper())
        sm = sum(1 for c in ext if c.islower())
        return cap - sm

    best_extension = extensions[0]
    max_strength = strength(best_extension)

    for ext in extensions[1:]:
        s = strength(ext)
        if s > max_strength:
            max_strength = s
            best_extension = ext

    return f"{class_name}.{best_extension}"

